function headFilterDescription(f){const parts=[];if(f.from||f.to)parts.push((f.from||'Any date')+' to '+(f.to||'today'));if(f.startHour!==undefined)parts.push(String(f.startHour).padStart(2,'0')+':00–'+String(f.endHour).padStart(2,'0')+':00 IST');if(f.status)parts.push(labels[f.status]||f.status);if(f.vehicleType)parts.push(f.vehicleType);if(f.text)parts.push(f.text);return parts.join(' · ')||'All visits'}
let headSource='browser',headTab='overview',headFilters={},headQuery='',headMessage='',headAI=false,headModel='',headProof='';
const headStore='amrita-head-v1';
let headSettings;try{headSettings=JSON.parse(localStorage.getItem(headStore))||{}}catch{headSettings={}}
headSettings={waiting:8,lanes:1,seconds:150,dwell:240,reviews:{},...headSettings};
headSource=headSettings.source||'browser';
function headSave(){try{localStorage.setItem(headStore,JSON.stringify(headSettings));if(window.SharedState)SharedState.enqueue()}catch{toast('Unable to save monitoring settings.')}}
function headData(){return headSource==='sample'?HeadEngine.fixtures():{visits,logs}}
function headDownload(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function headCSV(rows){const keys=['id','plate','visitor','relation','vehicleType','student','studentId','branch','hostel','warden','status','entered','exited','inspectionSeconds'];const cell=x=>{let t=String(x??'');if(/^[=+@-]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'};return[keys.map(cell).join(','),...rows.map(v=>keys.map(k=>cell(v[k])).join(','))].join('\r\n')}
function headTable(rows){return `<div class="table-scroll"><table><thead><tr><th>Visitor / vehicle</th><th>Student / hostel</th><th>Entry → exit (IST)</th><th>Status</th><th>History</th></tr></thead><tbody>${rows.map(v=>`<tr><td><strong>${esc(v.plate)}</strong>${esc(v.visitor)}<br><small>${esc(v.vehicleType||'Type not recorded')} · ${esc(v.id)}</small></td><td><strong>${esc(v.student)}</strong>${esc(v.hostel)}<br><small>${esc(v.branch)}</small></td><td>${stamp(v.entered)}<br>→ ${stamp(v.exited)}</td><td>${badge(v)}</td><td><button class="btn secondary table-btn" data-head-detail="${esc(v.id)}">View timeline</button> <button class="btn secondary table-btn" data-report-visit="${esc(v.id)}">Report concern</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No visits match your search.</td></tr>'}</tbody></table></div>`}
function headFacts(data,alerts,date){const rows=incidents.filter(i=>i.source===headSource);return [...HeadEngine.facts(data.visits,data.logs,date,alerts),{id:'incidents',text:rows.filter(i=>i.status!=='resolved').length+' unresolved incidents in this dataset.'},{id:'reports',text:rows.filter(i=>HeadEngine.day(i.created)===date).length+' incidents reported on '+date+'.'},{id:'inspections',text:data.visits.filter(v=>v.inspectionConfirmedAt&&HeadEngine.day(v.inspectionConfirmedAt)===date).length+' physical inspection confirmations recorded on '+date+'.'}]}
function securityHead(){
 const E=HeadEngine,data=headData(),alerts=E.anomalies(data.visits,new Date(),headSettings.dwell),open=alerts.filter(a=>!headSettings.reviews[headSource+':'+a.id]),forecast=E.forecast(data.visits),q=E.queue(headSettings.waiting,headSettings.lanes,headSettings.seconds),daily=headFacts(data,alerts,today()),matched=E.filter(data.visits,headFilters).sort((a,b)=>(b.entered||b.created||'').localeCompare(a.entered||a.created||''));
 app.innerHTML=heading('CAMPUS SECURITY / COMMAND CENTRE','Security head <span>monitoring</span>','A complete view of gate activity, inspection capacity and visits that need attention.')+`<div class="head-control"><div><span class="head-dot"></span><strong>Coimbatore campus</strong><small>All times shown in IST</small></div><label class="field">Data source<select id="head-source"><option value="browser">Current visit records</option><option value="sample">Sample history · 15 days</option></select></label><button class="btn secondary" id="head-refresh">Refresh monitoring</button></div><div class="head-source-note">${headSource==='sample'?'Sample history selected. These visits are demonstration data.':'Current visit records · Updates are shared across all portals.'}</div><div class="stats head-stats">${[['Entries today',data.visits.filter(v=>v.entered&&E.day(v.entered)===today()).length],['Currently inside',data.visits.filter(v=>v.entered&&!v.exited).length],['Pending approval',data.visits.filter(v=>effective(v)==='pending').length],['Flags awaiting review',open.length]].map(([s,n])=>`<div class="stat"><strong>${n}</strong><span>${s}</span></div>`).join('')}</div><div class="tabs head-tabs">${[['overview','Operations overview'],['incidents','Incidents & follow-up'],['history','Visit & audit history'],['intelligence','Search & daily briefing']].map(([id,title])=>`<button class="tab ${headTab===id?'active':''}" data-head-tab="${id}">${title}</button>`).join('')}</div><div id="head-body">${headTab==='overview'?`
 <div class="head-grid"><section class="panel"><div class="head-title"><h2>Inspection queue</h2><span class="head-tag">Manual count</span></div><p class="hint">Record waiting vehicles at the gate. Camera counting can replace this input later.</p><form id="queue-form" class="head-inputs"><label class="field">Waiting vehicles<input name="waiting" type="number" min="0" max="1000" required value="${headSettings.waiting}"></label><label class="field">Active inspection lanes<input name="lanes" type="number" min="1" max="10" required value="${headSettings.lanes}"></label><label class="field">Inspection seconds / vehicle<input name="seconds" type="number" min="10" max="1800" required value="${headSettings.seconds}"></label><button class="btn">Update estimate</button></form><div class="queue-metrics"><div><strong>${q.waitMinutes.toFixed(1)}<small> min</small></strong><span>Time to clear this queue*</span></div><div><strong>${q.capacity}</strong><span>Vehicles / hour capacity*</span></div></div><div class="head-advice">${q.suggest?'Consider an additional staffed inspection lane. Every vehicle still needs inspection.':'Queue is within the configured lane threshold. Keep inspecting every vehicle.'}</div><p class="hint">* Assumes equal service times and available lanes; arrivals and vehicles already being inspected are excluded. Lane suggestion triggers at 4 waiting vehicles per lane.</p><small class="hint">${headSettings.observed?'Last manual update: '+stamp(headSettings.observed):'Initial inputs are sample values. Enter a real observation to update.'}</small></section>
 <section class="panel"><div class="head-title"><h2>Peak-hour forecast</h2><span class="head-tag">Based on visit history</span></div><p class="hint">${esc(forecast.message)}</p>${forecast.bars.length?`<div class="head-chart" role="img" aria-label="Hourly average vehicle entries, IST">${forecast.bars.map(b=>`<div class="chart-column" title="${b.hour}:00 IST — ${b.value.toFixed(1)} entries / recorded day"><div style="height:${Math.max(2,b.value/Math.max(...forecast.bars.map(x=>x.value),1)*150)}px"></div><small>${b.hour%3===0?String(b.hour).padStart(2,'0'):''}</small></div>`).join('')}</div><div class="head-advice">Highest observed average: ${forecast.bars.filter(b=>b.value===Math.max(...forecast.bars.map(x=>x.value))).map(b=>String(b.hour).padStart(2,'0')+':00').join(', ')} IST. Consider staffing around these hours.</div>`:'<div class="head-empty">Forecast unavailable with this history.<br>Select sample history to demonstrate the chart.</div>'}<p class="hint">Counts completed-date entry records, not approval timestamps. Missing dates and incomplete collection can bias the estimate.</p></section></div>
 <section class="panel head-space"><div class="head-title"><h2>Unusual patterns to review</h2><span class="head-tag">Review alerts</span></div><div class="head-alert-settings"><label class="field">Long-visit threshold (minutes)<input id="head-dwell" type="number" min="30" max="10080" value="${headSettings.dwell}"></label><button class="btn secondary" id="head-threshold">Apply threshold</button></div><p class="hint">Outside-hours entries (before 06:00 or from 21:00) and long dwell times are review flags, not proof of wrongdoing.</p><div class="head-alerts">${alerts.map(a=>{const review=headSettings.reviews[headSource+':'+a.id];return`<article class="head-alert ${review?'reviewed':''}"><div><small>${esc(a.plate)} · ${esc(a.visit)}</small><strong>${esc(a.title)}</strong><p>${esc(a.detail)}</p>${review?`<small>Reviewed ${stamp(review.time)} · ${esc(review.note)}</small>`:''}</div><div>${review?'<span class="head-tag">Reviewed</span>':`<button class="btn secondary table-btn" data-head-review="${esc(a.id)}">Review flag</button>`}<button class="btn table-btn" data-report-flag="${esc(a.id)}">Report to team</button><button class="btn secondary table-btn" data-head-detail="${esc(a.visit)}">Visit details</button></div></article>`}).join('')||'<div class="head-empty">No patterns match the configured rules.</div>'}</div></section>`:headTab==='incidents'?incidentPanel('head'):headTab==='history'?`
 <section class="panel"><div class="head-title"><h2>Complete visit history</h2><button class="btn secondary" id="head-export">Export filtered CSV</button></div><form id="head-filter" class="head-filters"><label class="field">Visitor, plate, student or hostel<input name="text" value="${esc(headFilters.text||'')}" placeholder="Search recorded details"></label><label class="field">From date<input type="date" name="from" value="${headFilters.from||''}"></label><label class="field">To date<input type="date" name="to" value="${headFilters.to||''}"></label><label class="field">Status<select name="status"><option value="">All statuses</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${headFilters.status===k?'selected':''}>${v}</option>`).join('')}</select></label><button class="btn">Apply filters</button><button class="btn secondary" type="button" id="head-clear">Clear</button></form><p class="hint">${matched.length} matching records · Dates filter the entry date, or request creation date when no entry is recorded.</p>${headTable(matched)}</section><section class="panel head-space"><div class="head-title"><h2>Complete audit history</h2><button class="btn secondary" id="head-audit-export">Export audit JSON</button></div><p class="hint">${data.logs.length} events in selected dataset. Approval changes, entries and exits are recorded below.</p><div class="table-scroll"><table><thead><tr><th>Time (IST)</th><th>Vehicle / visit</th><th>Event</th><th>Recorded by</th></tr></thead><tbody>${data.logs.map(l=>`<tr><td>${stamp(l.time)}</td><td>${esc(l.plate)}<br><small>${esc(l.visit)}</small></td><td>${esc(l.action)}${l.original&&l.original!==l.plate?'<br>Original scan: '+esc(l.original):''}</td><td>${esc(l.actor)}</td></tr>`).join('')||'<tr><td colspan="4">No events yet.</td></tr>'}</tbody></table></div></section>`:`
 <div class="head-grid"><section class="panel"><div class="head-title"><h2>Search in plain language</h2><span class="head-tag" id="head-ai-badge">${headAI?'AI ready':'Standard search'}</span></div><p class="hint">Converts your question into visible filters, then retrieves actual visit records. It cannot approve a visit.</p><form id="head-search"><label class="field">What would you like to find?<input id="head-query" required maxlength="300" value="${esc(headQuery)}" placeholder="Visitor vans last Tuesday night"></label><div class="actions"><button class="btn" id="head-search-button">Search records</button><label class="check" style="margin:0"><input type="checkbox" id="head-use-ai" ${headAI?'checked':''} ${headAI?'':'disabled'}>Use AI</label></div></form><div class="sample-ids"><button type="button" class="sample-id" data-head-query="visitor vans last Tuesday night">Vans last Tuesday night</button><button type="button" class="sample-id" data-head-query="entries today">Entries today</button><button type="button" class="sample-id" data-head-query="completed visits yesterday">Completed yesterday</button></div><p class="hint">Supported fallback: today, yesterday, last weekday, ISO dates, night/morning, vehicle type, status and plate. The night filter means 18:00–05:59 on the selected calendar date.</p><div id="head-search-message" class="head-query-info" role="status">${esc(headMessage||'Run a query to see the interpreted filters.')}</div><div class="actions"><select id="head-model" hidden aria-label="Backend AI model">${headModel?'<option>'+esc(headModel)+'</option>':'<option>Connecting</option>'}</select><button type="button" id="head-ai-check" hidden>Check AI</button><button class="btn secondary" id="head-ai-test" ${headAI?'':'disabled'}>Test AI live</button></div><p id="head-ai-proof" class="head-query-info" role="status">${esc(headProof||'AI assistance is available for search and daily briefings.')}</p></section>
 <section class="panel"><div class="head-title"><h2>Daily security briefing</h2><span class="head-tag">Grounded in records</span></div><label class="field">Report date<input id="head-report-date" type="date" value="${today()}"></label><div class="actions"><button class="btn" id="head-summary">Generate report</button><button class="btn secondary" id="head-report-download">Download report</button></div><div id="head-report" class="head-report"><small>Daily summary · ${headSource==='sample'?'Sample history':'Current visit records'}</small><h3>Daily briefing · ${today()}</h3>${daily.map(f=>'<p>'+esc(f.text)+'</p>').join('')}<p class="hint">Inspection completeness cannot be established for older records that lack an inspection confirmation.</p></div></section></div><section class="panel head-space"><div class="head-title"><h2>Matching visit records</h2><button class="btn secondary" id="head-export">Export results CSV</button></div><p class="hint">${matched.length} matches · Search: ${esc(headFilterDescription(headFilters))}</p>${headTable(matched)}</section>`}</div><dialog id="head-dialog"><button class="btn secondary" id="head-dialog-close">Close</button><div id="head-dialog-content"></div></dialog>`;
 document.querySelector('#head-source').value=headSource;document.querySelector('#head-source').onchange=e=>{headSource=e.target.value;headSettings.source=headSource;headSave();headFilters={};headMessage='';securityHead()};
 document.querySelectorAll('[data-head-tab]').forEach(b=>b.onclick=()=>{headTab=b.dataset.headTab;securityHead()});
 document.querySelector('#head-refresh').onclick=()=>{securityHead();toast('Monitoring refreshed from the selected dataset.')};
 bindIncidents('head');
 document.querySelectorAll('[data-report-flag]').forEach(b=>b.onclick=()=>{const a=alerts.find(x=>x.id===b.dataset.reportFlag);reportIncident(a.visit,a)});document.querySelectorAll('[data-report-visit]').forEach(b=>b.onclick=()=>reportIncident(b.dataset.reportVisit));
 const on=(id,fn)=>{const el=document.getElementById(id);if(el)el.onclick=fn};
 on('head-export',()=>headDownload('visits-'+headSource+'.csv',headCSV(matched),'text/csv;charset=utf-8'));
 on('head-audit-export',()=>headDownload('audit-'+headSource+'.json',JSON.stringify(data.logs,null,2),'application/json'));
 document.querySelectorAll('[data-head-detail]').forEach(b=>b.onclick=()=>{const v=data.visits.find(x=>x.id===b.dataset.headDetail);if(!v)return;const timeline=data.logs.filter(l=>l.visit===v.id).sort((a,b)=>a.time.localeCompare(b.time));document.querySelector('#head-dialog-content').innerHTML=`<h2>${esc(v.plate)} · Visit timeline</h2><p>${esc(v.visitor)} → ${esc(v.student)}<br>${esc(v.hostel)} · ${esc(v.warden)}<br>${esc(v.id)} · ${badge(v)}</p><p>Purpose: ${esc(v.purpose)}<br>Visit date: ${esc(v.date)}<br>Phone: ${esc(v.phone||'Not recorded')}<br>Student ID: ${esc(v.studentId)}<br>Created: ${stamp(v.created)}</p><p>Inspection: ${v.inspectionConfirmed?'confirmed by guard':v.inspectionSeconds?'sample duration '+v.inspectionSeconds+'s':'not recorded'}</p>${timeline.map(l=>`<div class="head-timeline"><small>${stamp(l.time)} · ${esc(l.actor)}</small><strong>${esc(l.action)}</strong></div>`).join('')||'<p>No audit events for this visit.</p>'}`;document.querySelector('#head-dialog').showModal()});on('head-dialog-close',()=>document.querySelector('#head-dialog').close());
 const form=document.querySelector('#queue-form');if(form)form.onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(form));Object.keys(values).forEach(k=>headSettings[k]=Number(values[k]));headSettings.observed=new Date().toISOString();headSave();securityHead()};
 on('head-threshold',()=>{const input=document.querySelector('#head-dwell');if(!input.reportValidity())return;headSettings.dwell=Number(input.value);headSave();securityHead()});
 document.querySelectorAll('[data-head-review]').forEach(b=>b.onclick=()=>{const a=alerts.find(x=>x.id===b.dataset.headReview);document.querySelector('#head-dialog-content').innerHTML=`<h2>Review: ${esc(a.title)}</h2><p>${esc(a.detail)}</p><form id="head-review-form"><label class="field">Review note<textarea required maxlength="500" name="note" placeholder="Record your observation or follow-up"></textarea></label><button class="btn" style="margin-top:15px">Mark reviewed</button></form>`;document.querySelector('#head-dialog').showModal();document.querySelector('#head-review-form').onsubmit=e=>{e.preventDefault();const note=new FormData(e.target).get('note');headSettings.reviews[headSource+':'+a.id]={note,time:new Date().toISOString()};headSave();if(headSource==='browser'){const v=visits.find(x=>x.id===a.visit);if(v)audit('Security head reviewed flag',v,{actor:'Security head',flag:a.title,note})}securityHead();toast('Review recorded. Visit permission is unchanged.')}});
 const filters=document.querySelector('#head-filter');if(filters)filters.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(filters));if(f.from&&f.to&&f.from>f.to){toast('From date must be before the to date.');return}headFilters=f;securityHead()};on('head-clear',()=>{headFilters={};securityHead()});
 document.querySelectorAll('[data-head-query]').forEach(b=>b.onclick=()=>{document.querySelector('#head-query').value=b.dataset.headQuery;document.querySelector('#head-search').requestSubmit()});
 const search=document.querySelector('#head-search');if(search)search.onsubmit=async e=>{e.preventDefault();headQuery=document.querySelector('#head-query').value;const useAI=document.querySelector('#head-use-ai').checked;document.querySelector('#head-search-button').disabled=true;try{let result;if(useAI){const r=await fetch('/api/ai/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:headQuery,model:document.querySelector('#head-model').value,date:today()})});result=await r.json();if(!r.ok)throw Error(result.error)}else result=E.parse(headQuery);if(result.error){headMessage=result.error;document.querySelector('#head-search-message').textContent=headMessage;return}headFilters=result.filters;headMessage=(useAI?'AI search':'Search')+' · '+headFilterDescription(headFilters)+' · '+E.filter(data.visits,headFilters).length+' matching visits.';securityHead()}catch(err){headMessage='Search could not complete: '+err.message;document.querySelector('#head-search-message').textContent=headMessage}finally{const b=document.querySelector('#head-search-button');if(b)b.disabled=false}};
 on('head-ai-check',async()=>{const b=document.querySelector('#head-ai-check');b.disabled=true;try{const r=await fetch('/api/ai/status');if(!r.ok)throw Error();const status=await r.json();headAI=!!status.models?.length;const select=document.querySelector('#head-model');select.innerHTML=headAI?status.models.map(m=>'<option>'+esc(m)+'</option>').join(''):'<option>AI unavailable</option>';headModel=status.models?.[0]||'';document.querySelector('#head-use-ai').disabled=!headAI;document.querySelector('#head-use-ai').checked=headAI;document.querySelector('#head-ai-test').disabled=!headAI;document.querySelector('#head-ai-badge').textContent=headAI?'AI ready':'Standard search';if(!headAI)toast('AI is temporarily unavailable. Rule-based tools remain available.')}catch{toast('AI is temporarily unavailable. Standard search remains available.')}finally{b.disabled=false}});
 on('head-ai-test',async()=>{const b=document.querySelector('#head-ai-test');b.disabled=true;document.querySelector('#head-ai-proof').textContent='Running real model inference…';try{const r=await fetch('/api/ai/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:document.querySelector('#head-model').value})});const result=await r.json();if(!r.ok)throw Error(result.error);headProof='AI connection verified · '+result.ai.seconds+'s. '+result.reply;document.querySelector('#head-ai-proof').textContent=headProof}catch(err){document.querySelector('#head-ai-proof').textContent='AI test failed: '+err.message}finally{b.disabled=false}});
 on('head-summary',async()=>{const date=document.querySelector('#head-report-date').value;if(!date){toast('Choose a report date.');return}let facts=headFacts(data,alerts,date),mode='Daily summary';const b=document.querySelector('#head-summary');b.disabled=true;try{if(document.querySelector('#head-use-ai').checked){const r=await fetch('/api/ai/summary',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:document.querySelector('#head-model').value,facts})});const result=await r.json();if(!r.ok)throw Error(result.error);const order=result.ids;facts=[...order.map(id=>facts.find(f=>f.id===id)),...facts.filter(f=>!order.includes(f.id))];mode='AI-assisted briefing'}document.querySelector('#head-report').innerHTML='<small>'+esc(mode)+' · '+esc(headSource)+'</small><h3>Daily briefing · '+esc(date)+'</h3>'+facts.map(f=>'<p>'+esc(f.text)+'</p>').join('')+'<p class="hint">Every vehicle requires physical inspection. This report does not certify inspection completeness.</p>'}catch(err){toast('Report failed: '+err.message)}finally{b.disabled=false}});on('head-report-download',()=>headDownload('security-briefing-'+headSource+'.txt',document.querySelector('#head-report').innerText));
 if(headTab==='intelligence'&&!headAI)document.querySelector('#head-ai-check').click();
}
